(() => {
  const C = {
    "extensiones": "",
    "mantenimiento": "",
    "enlaces": "",
    "accesos": "",
    "beneficios": ""
  };
  const K = "aRi+Lf7PmCErlntLRpYAWSxLQgXYwd2B3Y2AiqtQbPA=";
  const rotl = (v, n) => (v << n) | (v >>> (32 - n));
  const qr = (x, a, b, c, d) => {
    x[a] += x[b]; x[d] = rotl(x[d] ^ x[a], 16);
    x[c] += x[d]; x[b] = rotl(x[b] ^ x[c], 12);
    x[a] += x[b]; x[d] = rotl(x[d] ^ x[a], 8);
    x[c] += x[d]; x[b] = rotl(x[b] ^ x[c], 7);
  };
  const w = (b, i) => b[i] | (b[i + 1] << 8) | (b[i + 2] << 16) | (b[i + 3] << 24);
  const flujo = (k, n, d) => {
    const o = new Uint8Array(d.length);
    const s = new Uint32Array(16);
    const x = new Uint32Array(16);
    s.set([0x61707865, 0x3320646e, 0x79622d32, 0x6b206574]);
    for (let i = 0; i < 8; i++) s[4 + i] = w(k, i * 4);
    for (let i = 0; i < 3; i++) s[13 + i] = w(n, i * 4);
    for (let p = 0, c = 0; p < d.length; p += 64, c++) {
      s[12] = c;
      x.set(s);
      for (let r = 0; r < 10; r++) {
        qr(x, 0, 4, 8, 12); qr(x, 1, 5, 9, 13); qr(x, 2, 6, 10, 14); qr(x, 3, 7, 11, 15);
        qr(x, 0, 5, 10, 15); qr(x, 1, 6, 11, 12); qr(x, 2, 7, 8, 13); qr(x, 3, 4, 9, 14);
      }
      for (let i = 0; i < 64 && p + i < d.length; i++) {
        o[p + i] = d[p + i] ^ (((x[i >> 2] + s[i >> 2]) >>> ((i & 3) * 8)) & 255);
      }
    }
    return o;
  };
  const b64 = (t) => Uint8Array.from(atob(t), (ch) => ch.charCodeAt(0));
  const cache = {};
  const leer = (nombre) => {
    if (!cache[nombre]) {
      const b = b64(C[nombre]);
      cache[nombre] = new TextDecoder().decode(flujo(b64(K), b.subarray(0, 12), b.subarray(12)));
    }
    return cache[nombre];
  };
  const original = window.fetch ? window.fetch.bind(window) : null;
  window.fetch = (entrada, opciones) => {
    const url = typeof entrada === 'string' ? entrada : (entrada && entrada.url) || '';
    const m = /^\/?(?:\.\/)?api\/([a-z]+)\/?$/.exec(url.split('?')[0]);
    if (m && Object.prototype.hasOwnProperty.call(C, m[1])) {
      return Promise.resolve(new Response(leer(m[1]), { status: 200, headers: { 'Content-Type': 'application/json' } }));
    }
    return original ? original(entrada, opciones) : Promise.reject(new TypeError('fetch no disponible'));
  };
})();
